\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{fontawesome5}
\pagestyle{empty}

% ── Dark Developer-Aesthetic Palette ──
\definecolor{bgdark}{HTML}{0D1117}       % poster background
\definecolor{cardbg}{HTML}{161B22}        % default card background
\definecolor{cardblue}{HTML}{111D2E}      % blue-tinted card bg
\definecolor{cardamber}{HTML}{1E1810}     % amber-tinted card bg
\definecolor{cardmint}{HTML}{121E18}      % green-tinted card bg
\definecolor{cardpurple}{HTML}{1A1525}    % purple-tinted card bg

\definecolor{blueE}{HTML}{58A6FF}         % electric blue (primary)
\definecolor{amberE}{HTML}{F0883E}        % amber (secondary)
\definecolor{mintE}{HTML}{3FB950}         % mint green (accent)
\definecolor{cyanE}{HTML}{39D2C0}         % cyan (highlight)
\definecolor{purpleE}{HTML}{BC8CFF}       % purple (tertiary)
\definecolor{redE}{HTML}{F85149}          % red (alert)

\definecolor{textwhite}{HTML}{E6EDF3}     % primary text
\definecolor{textgray}{HTML}{8B949E}      % secondary text
\definecolor{gridcolor}{HTML}{30363D}     % border/rule color

\definecolor{statbluebg}{HTML}{1A2840}    % stat highlight bg
\definecolor{statamberbg}{HTML}{281E14}
\definecolor{statmintbg}{HTML}{14281E}
\definecolor{statcyanbg}{HTML}{142826}

\pagecolor{bgdark}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{blueE}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=18pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{blueE}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{18}{22}\selectfont\color{textgray}\textit{#3}}\vspace{1mm}%
}

% ── Dark Card Styles (left accent stripe) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardblue,
    borderline west={5pt}{0pt}{blueE},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{blueE},
    coltitle=blueE, colbacktitle=cardblue,
    toptitle=3pt, bottomtitle=3pt,
    titlerule=1.5pt, titlerule style={blueE!40},
    valign=top, drop shadow={opacity=0.25, shadow={1mm}{-1mm}{0mm}{black!80}},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardamber,
    borderline west={5pt}{0pt}{amberE},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{amberE},
    coltitle=amberE, colbacktitle=cardamber,
    toptitle=3pt, bottomtitle=3pt,
    titlerule=1.5pt, titlerule style={amberE!40},
    valign=top, drop shadow={opacity=0.25, shadow={1mm}{-1mm}{0mm}{black!80}},
  },
  mintcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardmint,
    borderline west={5pt}{0pt}{mintE},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{mintE},
    coltitle=mintE, colbacktitle=cardmint,
    toptitle=3pt, bottomtitle=3pt,
    titlerule=1.5pt, titlerule style={mintE!40},
    valign=top, drop shadow={opacity=0.25, shadow={1mm}{-1mm}{0mm}{black!80}},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{textgray},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=cardbg,
    toptitle=3pt, bottomtitle=3pt,
    titlerule=1.5pt, titlerule style={gridcolor},
    valign=top, drop shadow={opacity=0.25, shadow={1mm}{-1mm}{0mm}{black!80}},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=blueE!18!bgdark,
    borderline west={6pt}{0pt}{blueE},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=blueE!60!bgdark,
    toptitle=3pt, bottomtitle=3pt,
    valign=top, drop shadow={opacity=0.30, shadow={1mm}{-1mm}{0mm}{black!80}},
  },
}

% ── Chart macro for full-width ──
\newcommand{\fullchart}[2]{%
  \centering\includegraphics[width=#1\linewidth]{#2}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════
% TITLE BAR (rows 0-3, span=2)
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=bgdark, colframe=bgdark, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=12pt, bottom=8pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{blueE!30}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{52}{62}\selectfont\bfseries\color{textwhite}State of Developer Ecosystem 2024}\\[6pt]
  {\fontsize{26}{32}\selectfont\color{blueE}\textbf{Language Wars \& Rising Stars}}\\[6pt]
  {\fontsize{20}{26}\selectfont\color{textgray}23,262 Developers Surveyed Worldwide \quad$\bullet$\quad JetBrains State of Developer Ecosystem 2024}
}

% ══════════════════════════════════════════
% STAT BANNER (rows 3-5, span=2) — 4 big callouts
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2pt}{0pt}{gridcolor},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    {\fontsize{36}{44}\selectfont\bfseries\color{mintE}TypeScript}\\[2pt]
    {\fontsize{48}{56}\selectfont\bfseries\color{mintE}199}\\[1pt]
    {\fontsize{16}{20}\selectfont\color{textgray}Promise Index \#1}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    {\fontsize{36}{44}\selectfont\bfseries\color{amberE}Python}\\[2pt]
    {\fontsize{48}{56}\selectfont\bfseries\color{amberE}57\%}\\[1pt]
    {\fontsize{16}{20}\selectfont\color{textgray}Usage in 2024}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    {\fontsize{36}{44}\selectfont\bfseries\color{blueE}JavaScript}\\[2pt]
    {\fontsize{48}{56}\selectfont\bfseries\color{blueE}61\%}\\[1pt]
    {\fontsize{16}{20}\selectfont\color{textgray}Most Used Language}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    {\fontsize{36}{44}\selectfont\bfseries\color{cyanE}AI + Dev}\\[2pt]
    {\fontsize{48}{56}\selectfont\bfseries\color{cyanE}18\%}\\[1pt]
    {\fontsize{16}{20}\selectfont\color{textgray}Build AI Integrations}
  \end{minipage}
}

% ══════════════════════════════════════════
% CENTERPIECE: Language Trajectory (rows 5-13, span=2)
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=6pt, bottom=6pt,
  valign=center, halign=center,
  borderline={1pt}{0pt}{gridcolor},
  drop shadow={opacity=0.25},
]{name=trajectory, column=1, span=2, between=row5 and row13}{
  \vspace{2mm}
  {\fontsize{32}{40}\selectfont\bfseries\color{textwhite}\centering Programming Language Usage Trends (2017--2024)\par}
  \vspace{3mm}
  \fullchart{0.96}{figures/language_trajectory.png}
  \vspace{2mm}
}

% ══════════════════════════════════════════
% COLUMN 1: Promise Index (rows 13-17)
% ══════════════════════════════════════════
\posterbox[mintcard, title={Rising Stars: Language Promise Index}
]{name=promise, column=1, between=row13 and row17}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \fullchart{0.96}{figures/promise_index.png}
  \vspace{1mm}
  \colorbox{mintE!18}{\parbox{0.92\linewidth}{\centering\fontsize{18}{24}\selectfont\color{mintE}\textbf{TypeScript (199)} leads -- signals where ecosystem is heading, not where it's been.}}
  \vspace{1mm}
  {\fontsize{17}{22}\selectfont\color{textgray}Growth stability + audience growth + intent to adopt + user retention.}
}

% ══════════════════════════════════════════
% COLUMN 2: Databases & Cloud (rows 13-17)
% ══════════════════════════════════════════
\posterbox[ambercard, title={Databases \& Cloud: Where Code Runs}
]{name=dbcloud, column=2, between=row13 and row17}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \fullchart{0.96}{figures/database_trends.png}
  \vspace{2mm}
  \fullchart{0.80}{figures/cloud_platforms.png}
}

% ══════════════════════════════════════════
% COLUMN 1: AI Integration (rows 17-20)
% ══════════════════════════════════════════
\posterbox[bluecard, title={AI in the Developer Workflow}
]{name=ai, column=1, between=row17 and bottom}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{18\%} of developers build AI integrations
    \item \textbf{Python dominates} AI/ML at 31\% of Python devs
    \item \textbf{11\% of C++ devs} active in AI/ML -- surprising for systems language
    \item Fear of AI among developers \textbf{diminishing} year over year
    \item \textbf{49\%} use Docker locally for development
  \end{itemize}
  \vspace{2mm}
  \colorbox{blueE!18}{\parbox{0.92\linewidth}{\centering\fontsize{17}{22}\selectfont\color{blueE}\textbf{AI is infiltrating production software at scale.}}}
}

% ══════════════════════════════════════════
% COLUMN 2: Dev Platforms + Key Takeaways (rows 17-20)
% ══════════════════════════════════════════
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=2, between=row17 and bottom}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{JavaScript (61\%)} still \#1 but \textbf{plateaued} -- Python (57\%) closing fast
    \item \textbf{TypeScript is the breakout story:} 12\% $\to$ 37\% in 8 years; Promise Index \#1 at 199
    \item \textbf{PostgreSQL surges} from 32\% $\to$ 45\%, challenging MySQL's lead
    \item \textbf{AWS at 46\%} cloud share; desktop (53\%) beats mobile (30\%)
    \item \textbf{Go \& Rust} most planned-to-adopt languages for performance
  \end{itemize}
  \vspace{2mm}
  {\fontsize{16}{20}\selectfont\color{textgray}Source: JetBrains State of Developer Ecosystem 2024 \quad$\bullet$\quad n=23,262}
}

\end{tcbposter}
\end{document}
LATEXEOF
